package main

import (
	"fmt"
	"io"
	"math"
	"os"
	"slices"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(num()), int(num())
	// Stream rows: keep each column's minimum and the minimum over all row maxima.
	columns := make([]int64, m)
	for j := range columns {
		columns[j] = math.MaxInt64
	}
	rowLimit := int64(math.MaxInt64)
	for i := 0; i < n; i++ {
		var largest int64
		for j := 0; j < m; j++ {
			v := num()
			largest = max(largest, v)
			columns[j] = min(columns[j], v)
		}
		rowLimit = min(rowLimit, largest)
	}
	// Column minima never exceed row maxima, so a saddle exists exactly when the extremes meet.
	answer := slices.Max(columns)
	if answer != rowLimit {
		answer = -1
	}
